1	// Command Registry - Centralized command management system
2	export interface ArgumentSchema {
3	  name: string;
4	  type: 'string' | 'number' | 'boolean' | 'choice';
5	  required?: boolean;
6	  choices?: string[];
7	  description?: string;
8	}
9	
10	export interface CommandContext {
11	  state?: Record<string, unknown>;
12	  permissions?: string[];
13	  environment?: 'development' | 'production';
14	  activeModule?: string;
15	}
16	
17	export interface ParsedArgs {
18	  [key: string]: string | number | boolean | string[] | undefined;
19	}
20	
21	export interface CommandResult {
22	  success: boolean;
23	  data?: unknown;
24	  error?: string;
25	}
26	
27	export interface Command {
28	  id: string;
29	  name: string;
30	  description: string;
31	  category?: string;
32	  keywords?: string[];
33	  args?: ArgumentSchema[];
34	  context?: CommandContext;
35	  handler: (args: ParsedArgs) => Promise<string>;
36	}
37	
38	export class CommandRegistry {
39	  private commands = new Map<string, Command>();
40	  private categories = new Set<string>();
41	  private version = 0;
42	
43	  register(command: Command): void {
44	    this.commands.set(command.id, command);
45	    if (command.category) {
46	      this.categories.add(command.category);
47	    }
48	    this.version++;
49	  }
50	
51	  unregister(id: string): void {
52	    const command = this.commands.get(id);
53	    if (command) {
54	      this.commands.delete(id);
55	      this.version++;
56	      // Note: We don't remove categories as other commands might use them
57	    }
58	  }
59	
60	  getCommands(context?: CommandContext): Command[] {
61	    const allCommands = Array.from(this.commands.values());
62	    
63	    if (!context) {
64	      return allCommands;
65	    }
66	
67	    // Filter commands based on context
68	    return allCommands.filter(command => {
69	      if (!command.context) return true;
70	      
71	      // Check module context
72	      if (command.context.activeModule && context.activeModule !== command.context.activeModule) {
73	        return false;
74	      }
75	
76	      // Check permissions
77	      if (command.context.permissions && context.permissions) {
78	        const hasPermission = command.context.permissions.some(permission => 
79	          context.permissions!.includes(permission)
80	        );
81	        if (!hasPermission) return false;
82	      }
83	
84	      // Check environment
85	      if (command.context.environment && context.environment !== command.context.environment) {
86	        return false;
87	      }
88	
89	      return true;
90	    });
91	  }
92	
93	  getCategories(): string[] {
94	    return Array.from(this.categories).sort();
95	  }
96	
97	  getCommand(id: string): Command | undefined {
98	    return this.commands.get(id);
99	  }
100	
101	  getVersion(): number {
102	    return this.version;
103	  }
104	
105	  searchCommands(query: string, context?: CommandContext): Command[] {
106	    const availableCommands = this.getCommands(context);
107	    
108	    if (!query.trim()) {
109	      return availableCommands;
110	    }
111	
112	    const queryLower = query.toLowerCase();
113	    
114	    return availableCommands.filter(command => {
115	      // Search in name
116	      if (command.name.toLowerCase().includes(queryLower)) return true;
117	      
118	      // Search in description
119	      if (command.description.toLowerCase().includes(queryLower)) return true;
120	      
121	      // Search in keywords
122	      if (command.keywords?.some(keyword => keyword.toLowerCase().includes(queryLower))) {
123	        return true;
124	      }
125	      
126	      // Search in category
127	      if (command.category?.toLowerCase().includes(queryLower)) return true;
128	      
129	      return false;
130	    });
131	  }
132	}
133	
134	// Global registry instance
135	export const commandRegistry = new CommandRegistry();

1	// Command Plugin System - Allow external modules to register commands
2	import { Command, commandRegistry } from './commandRegistry';
3	
4	export interface CommandPlugin {
5	  id: string;
6	  name: string;
7	  description: string;
8	  version: string;
9	  commands: Command[];
10	  onLoad?: () => void;
11	  onUnload?: () => void;
12	  dependencies?: string[];
13	}
14	
15	export class CommandPluginManager {
16	  private plugins = new Map<string, CommandPlugin>();
17	  private loadedPlugins = new Set<string>();
18	
19	  async loadPlugin(plugin: CommandPlugin): Promise<boolean> {
20	    try {
21	      // Check dependencies
22	      if (plugin.dependencies) {
23	        for (const dep of plugin.dependencies) {
24	          if (!this.isPluginLoaded(dep)) {
25	            console.warn(`Plugin ${plugin.id} requires dependency ${dep} which is not loaded`);
26	            return false;
27	          }
28	        }
29	      }
30	
31	      // Register commands
32	      for (const command of plugin.commands) {
33	        commandRegistry.register(command);
34	      }
35	
36	      // Store plugin
37	      this.plugins.set(plugin.id, plugin);
38	      this.loadedPlugins.add(plugin.id);
39	
40	      // Call onLoad hook
41	      if (plugin.onLoad) {
42	        await plugin.onLoad();
43	      }
44	
45	      console.log(`Plugin ${plugin.id} loaded successfully`);
46	      return true;
47	    } catch (error) {
48	      console.error(`Failed to load plugin ${plugin.id}:`, error);
49	      return false;
50	    }
51	  }
52	
53	  async unloadPlugin(pluginId: string): Promise<boolean> {
54	    try {
55	      const plugin = this.plugins.get(pluginId);
56	      if (!plugin) {
57	        console.warn(`Plugin ${pluginId} not found`);
58	        return false;
59	      }
60	
61	      // Check if other plugins depend on this one
62	      const dependentPlugins = Array.from(this.plugins.values()).filter(p =>
63	        p.dependencies?.includes(pluginId) && this.isPluginLoaded(p.id)
64	      );
65	
66	      if (dependentPlugins.length > 0) {
67	        const names = dependentPlugins.map(p => p.id).join(', ');
68	        console.warn(`Cannot unload plugin ${pluginId}: required by ${names}`);
69	        return false;
70	      }
71	
72	      // Unregister commands
73	      for (const command of plugin.commands) {
74	        commandRegistry.unregister(command.id);
75	      }
76	
77	      // Call onUnload hook
78	      if (plugin.onUnload) {
79	        await plugin.onUnload();
80	      }
81	
82	      // Remove from loaded set
83	      this.loadedPlugins.delete(pluginId);
84	
85	      console.log(`Plugin ${pluginId} unloaded successfully`);
86	      return true;
87	    } catch (error) {
88	      console.error(`Failed to unload plugin ${pluginId}:`, error);
89	      return false;
90	    }
91	  }
92	
93	  isPluginLoaded(pluginId: string): boolean {
94	    return this.loadedPlugins.has(pluginId);
95	  }
96	
97	  getLoadedPlugins(): CommandPlugin[] {
98	    return Array.from(this.loadedPlugins)
99	      .map(id => this.plugins.get(id))
100	      .filter(plugin => plugin !== undefined) as CommandPlugin[];
101	  }
102	
103	  getPlugin(pluginId: string): CommandPlugin | undefined {
104	    return this.plugins.get(pluginId);
105	  }
106	
107	  async reloadPlugin(pluginId: string): Promise<boolean> {
108	    const success = await this.unloadPlugin(pluginId);
109	    if (success) {
110	      const plugin = this.plugins.get(pluginId);
111	      if (plugin) {
112	        return await this.loadPlugin(plugin);
113	      }
114	    }
115	    return false;
116	  }
117	}
118	
119	// Global plugin manager
120	export const pluginManager = new CommandPluginManager();
121	
122	// Example utility functions for creating plugins
123	export const createPlugin = (config: Omit<CommandPlugin, 'commands'> & { commands?: Command[] }): CommandPlugin => ({
124	  commands: [],
125	  ...config
126	});
127	
128	// Plugin loader utilities
129	export const loadPluginsFromModule = async (moduleLoader: () => Promise<CommandPlugin[]>) => {
130	  try {
131	    const plugins = await moduleLoader();
132	    const results = await Promise.all(
133	      plugins.map(plugin => pluginManager.loadPlugin(plugin))
134	    );
135	    return results.every(success => success);
136	  } catch (error) {
137	    console.error('Failed to load plugins from module:', error);
138	    return false;
139	  }
140	};

1	const apiUrl = (import.meta.env.VITE_FUNCTION_URL as string | undefined) ?? '';
2	export const mcpUrl = apiUrl.replace(/\/?$/, '') + '/mcp';
3	
4	async function fetchJson(url: string, options: RequestInit) {
5	  const res = await fetch(url, options);
6	  if (!res.ok) {
7	    const text = await res.text();
8	    throw new Error(`HTTP ${res.status}: ${text}`);
9	  }
10	  return res.json();
11	}
12	
13	export interface JsonRpcResponse {
14	  jsonrpc: string;
15	  id: number | string | null;
16	  result?: unknown;
17	  error?: { code: number; message: string };
18	}
19	
20	export async function mcpRequest(
21	  method: string,
22	  params?: unknown,
23	  id: number | string = 1
24	): Promise<JsonRpcResponse> {
25	  const token = localStorage.getItem('authToken');
26	  const headers: Record<string, string> = {
27	    'Content-Type': 'application/json',
28	  };
29	
30	  // Include bearer token if available
31	  if (token) {
32	    headers['Authorization'] = `Bearer ${token}`;
33	  }
34	
35	  return fetchJson(mcpUrl, {
36	    method: 'POST',
37	    headers,
38	    body: JSON.stringify({ jsonrpc: '2.0', id, method, params }),
39	  });
40	}
41	
42	export async function callTool(name: string, args?: unknown) {
43	  return mcpRequest('tools/call', { name, arguments: args });
44	}
