1	// Command Context - Manage application state and contextual command availability
2	import { CommandContext } from './commandRegistry';
3	
4	export interface AppState {
5	  currentModule?: string;
6	  userPermissions: string[];
7	  environment: 'development' | 'production';
8	  connectionStatus: 'connected' | 'disconnected' | 'connecting';
9	  lastApiResponse?: unknown;
10	  selectedItems?: string[];
11	  activeTab?: string;
12	  [key: string]: unknown;
13	}
14	
15	export class CommandContextManager {
16	  private state: AppState = {
17	    userPermissions: ['read', 'write'], // Default permissions
18	    environment: process.env.NODE_ENV as 'development' | 'production' || 'development',
19	    connectionStatus: 'disconnected'
20	  };
21	
22	  private listeners = new Set<(context: CommandContext) => void>();
23	
24	  setState(updates: Partial<AppState>): void {
25	    const oldState = { ...this.state };
26	    this.state = { ...this.state, ...updates };
27	    
28	    // Notify listeners if context changed
29	    const oldContext = this.createContext(oldState);
30	    const newContext = this.createContext(this.state);
31	    
32	    if (this.hasContextChanged(oldContext, newContext)) {
33	      this.notifyListeners(newContext);
34	    }
35	  }
36	
37	  getState(): AppState {
38	    return { ...this.state };
39	  }
40	
41	  getContext(): CommandContext {
42	    return this.createContext(this.state);
43	  }
44	
45	  onContextChange(listener: (context: CommandContext) => void): () => void {
46	    this.listeners.add(listener);
47	    
48	    // Return unsubscribe function
49	    return () => {
50	      this.listeners.delete(listener);
51	    };
52	  }
53	
54	  // Specific state management methods
55	  setModule(module: string): void {
56	    this.setState({ currentModule: module });
57	  }
58	
59	  setConnectionStatus(status: AppState['connectionStatus']): void {
60	    this.setState({ connectionStatus: status });
61	  }
62	
63	  setPermissions(permissions: string[]): void {
64	    this.setState({ userPermissions: permissions });
65	  }
66	
67	  addPermission(permission: string): void {
68	    if (!this.state.userPermissions.includes(permission)) {
69	      this.setState({
70	        userPermissions: [...this.state.userPermissions, permission]
71	      });
72	    }
73	  }
74	
75	  removePermission(permission: string): void {
76	    this.setState({
77	      userPermissions: this.state.userPermissions.filter(p => p !== permission)
78	    });
79	  }
80	
81	  setLastApiResponse(response: unknown): void {
82	    this.setState({ lastApiResponse: response });
83	  }
84	
85	  selectItems(items: string[]): void {
86	    this.setState({ selectedItems: items });
87	  }
88	
89	  clearSelection(): void {
90	    this.setState({ selectedItems: undefined });
91	  }
92	
93	  setActiveTab(tab: string): void {
94	    this.setState({ activeTab: tab });
95	  }
96	
97	  // Helper methods for common checks
98	  hasPermission(permission: string): boolean {
99	    return this.state.userPermissions.includes(permission);
100	  }
101	
102	  isConnected(): boolean {
103	    return this.state.connectionStatus === 'connected';
104	  }
105	
106	  isInModule(module: string): boolean {
107	    return this.state.currentModule === module;
108	  }
109	
110	  hasSelectedItems(): boolean {
111	    return Boolean(this.state.selectedItems && this.state.selectedItems.length > 0);
112	  }
113	
114	  private createContext(state: AppState): CommandContext {
115	    return {
116	      state: { ...state },
117	      permissions: [...state.userPermissions],
118	      environment: state.environment,
119	      activeModule: state.currentModule
120	    };
121	  }
122	
123	  private hasContextChanged(oldContext: CommandContext, newContext: CommandContext): boolean {
124	    // Check if relevant context properties changed
125	    if (oldContext.activeModule !== newContext.activeModule) return true;
126	    if (oldContext.environment !== newContext.environment) return true;
127	    
128	    // Check permissions
129	    if (oldContext.permissions?.length !== newContext.permissions?.length) return true;
130	    if (oldContext.permissions?.some(p => !newContext.permissions?.includes(p))) return true;
131	    
132	    return false;
133	  }
134	
135	  private notifyListeners(context: CommandContext): void {
136	    this.listeners.forEach(listener => {
137	      try {
138	        listener(context);
139	      } catch (error) {
140	        console.error('Error in context change listener:', error);
141	      }
142	    });
143	  }
144	}
145	
146	// Global context manager
147	export const contextManager = new CommandContextManager();
148	
149	// Utility functions
150	export const withContext = <T extends unknown[]>(
151	  fn: (...args: T) => unknown,
152	  requiredPermissions?: string[],
153	  requiredModule?: string
154	) => {
155	  return (...args: T) => {
156	    const context = contextManager.getContext();
157	    
158	    if (requiredPermissions) {
159	      const hasAllPermissions = requiredPermissions.every(permission =>
160	        context.permissions?.includes(permission)
161	      );
162	      if (!hasAllPermissions) {
163	        throw new Error(`Insufficient permissions. Required: ${requiredPermissions.join(', ')}`);
164	      }
165	    }
166	    
167	    if (requiredModule && context.activeModule !== requiredModule) {
168	      throw new Error(`This command is only available in the ${requiredModule} module`);
169	    }
170	    
171	    return fn(...args);
172	  };
173	};
174	
175	// Hook-like function for React components (if needed)
176	export const useCommandContext = () => {
177	  return {
178	    state: contextManager.getState(),
179	    context: contextManager.getContext(),
180	    setState: contextManager.setState.bind(contextManager),
181	    setModule: contextManager.setModule.bind(contextManager),
182	    setConnectionStatus: contextManager.setConnectionStatus.bind(contextManager),
183	    hasPermission: contextManager.hasPermission.bind(contextManager),
184	    isConnected: contextManager.isConnected.bind(contextManager),
185	    isInModule: contextManager.isInModule.bind(contextManager)
186	  };
187	};

