1	// Command Plugin System - Allow external modules to register commands
2	import { Command, commandRegistry } from './commandRegistry';
3	
4	export interface CommandPlugin {
5	  id: string;
6	  name: string;
7	  description: string;
8	  version: string;
9	  commands: Command[];
10	  onLoad?: () => void;
11	  onUnload?: () => void;
12	  dependencies?: string[];
13	}
14	
15	export class CommandPluginManager {
16	  private plugins = new Map<string, CommandPlugin>();
17	  private loadedPlugins = new Set<string>();
18	
19	  async loadPlugin(plugin: CommandPlugin): Promise<boolean> {
20	    try {
21	      // Check dependencies
22	      if (plugin.dependencies) {
23	        for (const dep of plugin.dependencies) {
24	          if (!this.isPluginLoaded(dep)) {
25	            console.warn(`Plugin ${plugin.id} requires dependency ${dep} which is not loaded`);
26	            return false;
27	          }
28	        }
29	      }
30	
31	      // Register commands
32	      for (const command of plugin.commands) {
33	        commandRegistry.register(command);
34	      }
35	
36	      // Store plugin
37	      this.plugins.set(plugin.id, plugin);
38	      this.loadedPlugins.add(plugin.id);
39	
40	      // Call onLoad hook
41	      if (plugin.onLoad) {
42	        await plugin.onLoad();
43	      }
44	
45	      console.log(`Plugin ${plugin.id} loaded successfully`);
46	      return true;
47	    } catch (error) {
48	      console.error(`Failed to load plugin ${plugin.id}:`, error);
49	      return false;
50	    }
51	  }
52	
53	  async unloadPlugin(pluginId: string): Promise<boolean> {
54	    try {
55	      const plugin = this.plugins.get(pluginId);
56	      if (!plugin) {
57	        console.warn(`Plugin ${pluginId} not found`);
58	        return false;
59	      }
60	
61	      // Check if other plugins depend on this one
62	      const dependentPlugins = Array.from(this.plugins.values()).filter(p =>
63	        p.dependencies?.includes(pluginId) && this.isPluginLoaded(p.id)
64	      );
65	
66	      if (dependentPlugins.length > 0) {
67	        const names = dependentPlugins.map(p => p.id).join(', ');
68	        console.warn(`Cannot unload plugin ${pluginId}: required by ${names}`);
69	        return false;
70	      }
71	
72	      // Unregister commands
73	      for (const command of plugin.commands) {
74	        commandRegistry.unregister(command.id);
75	      }
76	
77	      // Call onUnload hook
78	      if (plugin.onUnload) {
79	        await plugin.onUnload();
80	      }
81	
82	      // Remove from loaded set
83	      this.loadedPlugins.delete(pluginId);
84	
85	      console.log(`Plugin ${pluginId} unloaded successfully`);
86	      return true;
87	    } catch (error) {
88	      console.error(`Failed to unload plugin ${pluginId}:`, error);
89	      return false;
90	    }
91	  }
92	
93	  isPluginLoaded(pluginId: string): boolean {
94	    return this.loadedPlugins.has(pluginId);
95	  }
96	
97	  getLoadedPlugins(): CommandPlugin[] {
98	    return Array.from(this.loadedPlugins)
99	      .map(id => this.plugins.get(id))
100	      .filter(plugin => plugin !== undefined) as CommandPlugin[];
101	  }
102	
103	  getPlugin(pluginId: string): CommandPlugin | undefined {
104	    return this.plugins.get(pluginId);
105	  }
106	
107	  async reloadPlugin(pluginId: string): Promise<boolean> {
108	    const success = await this.unloadPlugin(pluginId);
109	    if (success) {
110	      const plugin = this.plugins.get(pluginId);
111	      if (plugin) {
112	        return await this.loadPlugin(plugin);
113	      }
114	    }
115	    return false;
116	  }
117	}
