1	// Command Context - Manage application state and contextual command availability
2	import { CommandContext } from './commandRegistry';
3	
4	export interface AppState {
5	  currentModule?: string;
6	  userPermissions: string[];
7	  environment: 'development' | 'production';
8	  connectionStatus: 'connected' | 'disconnected' | 'connecting';
9	  lastApiResponse?: unknown;
10	  selectedItems?: string[];
11	  activeTab?: string;
12	  [key: string]: unknown;
13	}
14	
15	export class CommandContextManager {
16	  private state: AppState = {
17	    userPermissions: ['read', 'write'], // Default permissions
18	    environment: process.env.NODE_ENV as 'development' | 'production' || 'development',
19	    connectionStatus: 'disconnected'
20	  };
21	
22	  private listeners = new Set<(context: CommandContext) => void>();
23	
24	  setState(updates: Partial<AppState>): void {
25	    const oldState = { ...this.state };
26	    this.state = { ...this.state, ...updates };
27	    
28	    // Notify listeners if context changed
29	    const oldContext = this.createContext(oldState);
30	    const newContext = this.createContext(this.state);
31	    
32	    if (this.hasContextChanged(oldContext, newContext)) {
33	      this.notifyListeners(newContext);
34	    }
35	  }
36	
37	  getState(): AppState {
38	    return { ...this.state };
39	  }
40	
41	  getContext(): CommandContext {
42	    return this.createContext(this.state);
43	  }
44	
45	  onContextChange(listener: (context: CommandContext) => void): () => void {
46	    this.listeners.add(listener);
47	    
48	    // Return unsubscribe function
49	    return () => {
50	      this.listeners.delete(listener);
51	    };
52	  }
53	
54	  // Specific state management methods
55	  setModule(module: string): void {
56	    this.setState({ currentModule: module });
57	  }
58	
59	  setConnectionStatus(status: AppState['connectionStatus']): void {
60	    this.setState({ connectionStatus: status });
61	  }
62	
63	  setPermissions(permissions: string[]): void {
64	    this.setState({ userPermissions: permissions });
65	  }
66	
67	  addPermission(permission: string): void {
68	    if (!this.state.userPermissions.includes(permission)) {
69	      this.setState({
70	        userPermissions: [...this.state.userPermissions, permission]
71	      });
72	    }
73	  }
74	
75	  removePermission(permission: string): void {
76	    this.setState({
77	      userPermissions: this.state.userPermissions.filter(p => p !== permission)
78	    });
79	  }
80	
81	  setLastApiResponse(response: unknown): void {
82	    this.setState({ lastApiResponse: response });
83	  }
84	
85	  selectItems(items: string[]): void {
86	    this.setState({ selectedItems: items });
87	  }
88	
89	  clearSelection(): void {
90	    this.setState({ selectedItems: undefined });
91	  }
92	
93	  setActiveTab(tab: string): void {
94	    this.setState({ activeTab: tab });
95	  }
96	
97	  // Helper methods for common checks
98	  hasPermission(permission: string): boolean {
99	    return this.state.userPermissions.includes(permission);
100	  }
101	
102	  isConnected(): boolean {
103	    return this.state.connectionStatus === 'connected';
104	  }
105	
106	  isInModule(module: string): boolean {
107	    return this.state.currentModule === module;
108	  }
109	
110	  hasSelectedItems(): boolean {
111	    return Boolean(this.state.selectedItems && this.state.selectedItems.length > 0);
112	  }
113	
114	  private createContext(state: AppState): CommandContext {
115	    return {
116	      state: { ...state },
117	      permissions: [...state.userPermissions],
118	      environment: state.environment,
119	      activeModule: state.currentModule
120	    };
121	  }
122	
123	  private hasContextChanged(oldContext: CommandContext, newContext: CommandContext): boolean {
124	    // Check if relevant context properties changed
125	    if (oldContext.activeModule !== newContext.activeModule) return true;
126	    if (oldContext.environment !== newContext.environment) return true;
127	    
128	    // Check permissions
129	    if (oldContext.permissions?.length !== newContext.permissions?.length) return true;
130	    if (oldContext.permissions?.some(p => !newContext.permissions?.includes(p))) return true;
131	    
132	    return false;
133	  }
134	
135	  private notifyListeners(context: CommandContext): void {
136	    this.listeners.forEach(listener => {
137	      try {
138	        listener(context);
139	      } catch (error) {
140	        console.error('Error in context change listener:', error);
141	      }
142	    });
143	  }
144	}
145	
146	// Global context manager
147	export const contextManager = new CommandContextManager();
148	
149	// Utility functions
150	export const withContext = <T extends unknown[]>(
151	  fn: (...args: T) => unknown,
152	  requiredPermissions?: string[],
153	  requiredModule?: string
154	) => {
155	  return (...args: T) => {
156	    const context = contextManager.getContext();
157	    
158	    if (requiredPermissions) {
159	      const hasAllPermissions = requiredPermissions.every(permission =>
160	        context.permissions?.includes(permission)
161	      );
162	      if (!hasAllPermissions) {
163	        throw new Error(`Insufficient permissions. Required: ${requiredPermissions.join(', ')}`);
164	      }
165	    }
166	    
167	    if (requiredModule && context.activeModule !== requiredModule) {
168	      throw new Error(`This command is only available in the ${requiredModule} module`);
169	    }
170	    
171	    return fn(...args);
172	  };
173	};
174	
175	// Hook-like function for React components (if needed)
176	export const useCommandContext = () => {
177	  return {
178	    state: contextManager.getState(),
179	    context: contextManager.getContext(),
180	    setState: contextManager.setState.bind(contextManager),
181	    setModule: contextManager.setModule.bind(contextManager),
182	    setConnectionStatus: contextManager.setConnectionStatus.bind(contextManager),
183	    hasPermission: contextManager.hasPermission.bind(contextManager),
184	    isConnected: contextManager.isConnected.bind(contextManager),
185	    isInModule: contextManager.isInModule.bind(contextManager)
186	  };
187	};

1	// Command Suggestions - Generate command suggestions based on context and usage
2	import { Command } from './commandRegistry';
3	import { commandHistory } from './commandHistory';
4	
5	export interface SuggestionReason {
6	  type: 'related' | 'frequent' | 'recent' | 'category';
7	  reason: string;
8	}
9	
10	export interface CommandSuggestion {
11	  command: Command;
12	  reason: SuggestionReason;
13	  score: number;
14	}
15	
16	export class CommandSuggestionEngine {
17	  generateSuggestions(
18	    lastExecutedCommand: Command, 
19	    allCommands: Command[], 
20	    limit: number = 3
21	  ): CommandSuggestion[] {
22	    const suggestions: CommandSuggestion[] = [];
23	
24	    // Related commands (same category)
25	    const relatedCommands = allCommands.filter(cmd => 
26	      cmd.category === lastExecutedCommand.category && 
27	      cmd.id !== lastExecutedCommand.id
28	    );
29	
30	    for (const cmd of relatedCommands) {
31	      suggestions.push({
32	        command: cmd,
33	        reason: {
34	          type: 'category',
35	          reason: `Similar to ${lastExecutedCommand.name} (${cmd.category})`
36	        },
37	        score: 0.7
38	      });
39	    }
40	
41	    // Frequently used commands
42	    const mostUsed = commandHistory.getMostUsedCommands(5);
43	    for (const { name, count } of mostUsed) {
44	      const cmd = allCommands.find(c => c.name === name);
45	      if (cmd && cmd.id !== lastExecutedCommand.id) {
46	        suggestions.push({
47	          command: cmd,
48	          reason: {
49	            type: 'frequent',
50	            reason: `Frequently used (${count} times)`
51	          },
52	          score: 0.6 + (count * 0.1)
53	        });
54	      }
55	    }
56	
57	    // Recently used commands
58	    const recent = commandHistory.getRecentCommands(5);
59	    for (let i = 0; i < recent.length; i++) {
60	      const recentCommandName = recent[i].split(' ')[0]; // Get command name without args
61	      const cmd = allCommands.find(c => c.name === recentCommandName);
62	      if (cmd && cmd.id !== lastExecutedCommand.id) {
63	        suggestions.push({
64	          command: cmd,
65	          reason: {
66	            type: 'recent',
67	            reason: `Recently used`
68	          },
69	          score: 0.5 + ((5 - i) * 0.1) // More recent = higher score
70	        });
71	      }
72	    }
73	
74	    // Command-specific relationships
75	    const specific = this.getSpecificSuggestions(lastExecutedCommand, allCommands);
76	    suggestions.push(...specific);
77	
78	    // Sort by score and remove duplicates
79	    const uniqueSuggestions = new Map<string, CommandSuggestion>();
80	    for (const suggestion of suggestions) {
81	      const existing = uniqueSuggestions.get(suggestion.command.id);
82	      if (!existing || existing.score < suggestion.score) {
83	        uniqueSuggestions.set(suggestion.command.id, suggestion);
84	      }
85	    }
86	
87	    return Array.from(uniqueSuggestions.values())
88	      .sort((a, b) => b.score - a.score)
89	      .slice(0, limit);
90	  }
91	
92	  private getSpecificSuggestions(lastCommand: Command, allCommands: Command[]): CommandSuggestion[] {
93	    const suggestions: CommandSuggestion[] = [];
94	
95	    // Define command relationships
96	    const relationships: Record<string, string[]> = {
97	      'system.status': ['mcp.capabilities', 'mcp.list-tools'],
98	      'mcp.capabilities': ['mcp.list-tools', 'mcp.echo'],
99	      'mcp.list-tools': ['tools.call-dynamo', 'mcp.echo'],
100	      'tools.call-dynamo': ['mcp.list-tools', 'system.status'],
101	      'mcp.echo': ['mcp.capabilities', 'system.help']
102	    };
103	
104	    const related = relationships[lastCommand.id];
105	    if (related) {
106	      for (const commandId of related) {
107	        const cmd = allCommands.find(c => c.id === commandId);
108	        if (cmd) {
109	          suggestions.push({
110	            command: cmd,
111	            reason: {
112	              type: 'related',
113	              reason: `Works well with ${lastCommand.name}`
114	            },
115	            score: 0.8
116	          });
117	        }
118	      }
119	    }
120	
121	    return suggestions;
122	  }
123	}
124	
125	export const suggestionEngine = new CommandSuggestionEngine();

1	// Command History - Track and manage command execution history
2	export interface HistoryEntry {
3	  id: string;
4	  commandName: string;
5	  args: string[];
6	  timestamp: Date;
7	  result?: string;
8	  error?: string;
9	}
10	
11	export class CommandHistory {
12	  private history: HistoryEntry[] = [];
13	  private maxHistory: number = 50;
14	
15	  addEntry(commandName: string, args: string[], result?: string, error?: string): void {
16	    const entry: HistoryEntry = {
17	      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
18	      commandName,
19	      args,
20	      timestamp: new Date(),
21	      result,
22	      error
23	    };
24	
25	    this.history.unshift(entry); // Add to beginning
26	
27	    // Keep only the most recent entries
28	    if (this.history.length > this.maxHistory) {
29	      this.history = this.history.slice(0, this.maxHistory);
30	    }
31	
32	    // Persist to localStorage
33	    this.saveToStorage();
34	  }
35	
36	  getHistory(): HistoryEntry[] {
37	    return [...this.history];
38	  }
39	
40	  getRecentCommands(limit: number = 10): string[] {
41	    const recent = new Set<string>();
42	    
43	    for (const entry of this.history) {
44	      if (recent.size >= limit) break;
45	      const fullCommand = entry.args.length > 0 
46	        ? `${entry.commandName} ${entry.args.join(' ')}`
47	        : entry.commandName;
48	      recent.add(fullCommand);
49	    }
50	    
51	    return Array.from(recent);
52	  }
53	
54	  getCommandUsageCount(commandName: string): number {
55	    return this.history.filter(entry => entry.commandName === commandName).length;
56	  }
57	
58	  getMostUsedCommands(limit: number = 5): Array<{ name: string; count: number }> {
59	    const counts = new Map<string, number>();
60	    
61	    for (const entry of this.history) {
62	      const current = counts.get(entry.commandName) || 0;
63	      counts.set(entry.commandName, current + 1);
64	    }
65	    
66	    return Array.from(counts.entries())
67	      .map(([name, count]) => ({ name, count }))
68	      .sort((a, b) => b.count - a.count)
69	      .slice(0, limit);
70	  }
71	
72	  clear(): void {
73	    this.history = [];
74	    this.saveToStorage();
75	  }
76	
77	  private saveToStorage(): void {
78	    try {
79	      localStorage.setItem('commandHistory', JSON.stringify(this.history));
80	    } catch (e) {
81	      // localStorage might not be available
82	      console.warn('Could not save command history to localStorage:', e);
83	    }
84	  }
85	
86	  private loadFromStorage(): void {
87	    try {
88	      const stored = localStorage.getItem('commandHistory');
89	      if (stored) {
90	        const parsed = JSON.parse(stored) as Array<Omit<HistoryEntry, 'timestamp'> & { timestamp: string }>;
91	        // Convert timestamp strings back to Date objects
92	        this.history = parsed.map((entry) => ({
93	          ...entry,
94	          timestamp: new Date(entry.timestamp)
95	        }));
96	      }
97	    } catch (e) {
98	      console.warn('Could not load command history from localStorage:', e);
99	      this.history = [];
100	    }
101	  }
102	
103	  constructor() {
104	    this.loadFromStorage();
105	  }
106	}
107	
108	// Global history instance
109	export const commandHistory = new CommandHistory();

1	// Command Macros - Chain multiple commands together with conditional execution
2	import { Command, commandRegistry } from './commandRegistry';
3	
4	export interface MacroStep {
5	  commandId: string;
6	  args?: Record<string, string | number | boolean>;
7	  condition?: 'always' | 'on-success' | 'on-failure';
8	  description?: string;
9	}
10	
11	export interface CommandMacro {
12	  id: string;
13	  name: string;
14	  description: string;
15	  steps: MacroStep[];
16	  category?: string;
17	  keywords?: string[];
18	}
19	
20	export interface MacroExecutionResult {
21	  success: boolean;
22	  results: Array<{
23	    step: MacroStep;
24	    result?: string;
25	    error?: string;
26	    skipped?: boolean;
27	  }>;
28	  totalSteps: number;
29	  executedSteps: number;
30	}
31	
32	export class CommandMacroManager {
33	  private macros = new Map<string, CommandMacro>();
34	
35	  registerMacro(macro: CommandMacro): void {
36	    // Create a command for this macro
37	    const command: Command = {
38	      id: `macro.${macro.id}`,
39	      name: macro.name,
40	      description: `${macro.description} (${macro.steps.length} steps)`,
41	      category: macro.category || 'Macros',
42	      keywords: [...(macro.keywords || []), 'macro', 'chain'],
43	      handler: async () => {
44	        const result = await this.executeMacro(macro.id);
45	        return this.formatMacroResult(result);
46	      }
47	    };
48	
49	    commandRegistry.register(command);
50	    this.macros.set(macro.id, macro);
51	  }
52	
53	  unregisterMacro(macroId: string): void {
54	    commandRegistry.unregister(`macro.${macroId}`);
55	    this.macros.delete(macroId);
56	  }
57	
58	  getMacro(macroId: string): CommandMacro | undefined {
59	    return this.macros.get(macroId);
60	  }
61	
62	  getMacros(): CommandMacro[] {
63	    return Array.from(this.macros.values());
64	  }
65	
66	  async executeMacro(macroId: string): Promise<MacroExecutionResult> {
67	    const macro = this.macros.get(macroId);
68	    if (!macro) {
69	      throw new Error(`Macro ${macroId} not found`);
70	    }
71	
72	    const result: MacroExecutionResult = {
73	      success: true,
74	      results: [],
75	      totalSteps: macro.steps.length,
76	      executedSteps: 0
77	    };
78	
79	    let lastStepSuccess = true;
80	
81	    for (const step of macro.steps) {
82	      const stepResult = {
83	        step,
84	        result: undefined as string | undefined,
85	        error: undefined as string | undefined,
86	        skipped: false
87	      };
88	
89	      // Check execution condition
90	      const shouldExecute = this.shouldExecuteStep(step, lastStepSuccess);
91	      
92	      if (!shouldExecute) {
93	        stepResult.skipped = true;
94	        result.results.push(stepResult);
95	        continue;
96	      }
97	
98	      try {
99	        const command = commandRegistry.getCommand(step.commandId);
100	        if (!command) {
101	          throw new Error(`Command ${step.commandId} not found`);
102	        }
103	
104	        const args = step.args || {};
105	        stepResult.result = await command.handler(args);
106	        lastStepSuccess = true;
107	        result.executedSteps++;
108	      } catch (error) {
109	        stepResult.error = error instanceof Error ? error.message : String(error);
110	        lastStepSuccess = false;
111	        result.success = false;
112	      }
113	
114	      result.results.push(stepResult);
115	
116	      // If this step failed and it's critical, stop execution
117	      if (!lastStepSuccess && step.condition !== 'on-failure') {
118	        break;
119	      }
120	    }
121	
122	    return result;
123	  }
124	
125	  private shouldExecuteStep(step: MacroStep, lastStepSuccess: boolean): boolean {
126	    switch (step.condition) {
127	      case 'on-success':
128	        return lastStepSuccess;
129	      case 'on-failure':
130	        return !lastStepSuccess;
131	      case 'always':
132	      default:
133	        return true;
134	    }
135	  }
136	
137	  private formatMacroResult(result: MacroExecutionResult): string {
138	    let output = `Macro execution ${result.success ? 'completed' : 'failed'}\n`;
139	    output += `Executed ${result.executedSteps}/${result.totalSteps} steps\n\n`;
140	
141	    for (let i = 0; i < result.results.length; i++) {
142	      const stepResult = result.results[i];
143	      const stepNum = i + 1;
144	      
145	      if (stepResult.skipped) {
146	        output += `Step ${stepNum}: SKIPPED (${stepResult.step.commandId})\n`;
147	        if (stepResult.step.description) {
148	          output += `  ${stepResult.step.description}\n`;
149	        }
150	        output += '\n';
151	        continue;
152	      }
153	
154	      const status = stepResult.error ? 'FAILED' : 'SUCCESS';
155	      output += `Step ${stepNum}: ${status} (${stepResult.step.commandId})\n`;
156	      
157	      if (stepResult.step.description) {
158	        output += `  ${stepResult.step.description}\n`;
159	      }
160	
161	      if (stepResult.result) {
162	        const preview = stepResult.result.length > 100 
163	          ? stepResult.result.substring(0, 100) + '...'
164	          : stepResult.result;
165	        output += `  Result: ${preview}\n`;
166	      }
167	
168	      if (stepResult.error) {
169	        output += `  Error: ${stepResult.error}\n`;
170	      }
171	
172	      output += '\n';
173	    }
174	
175	    return output;
176	  }
177	}
