190	    description?: string;
191	  }
192	): MacroStep => ({
193	  commandId,
194	  args,
195	  condition: options?.condition || 'always',
196	  description: options?.description
197	});

1	// Command Templates - Pre-configured command patterns and templates
2	import { Command, ArgumentSchema } from './commandRegistry';
3	import { CommandMacro, createMacro, createMacroStep } from './commandMacro';
4	
5	export interface CommandTemplate {
6	  id: string;
7	  name: string;
8	  description: string;
9	  category: string;
10	  pattern: string; // Template with placeholders like {{param}}
11	  args: ArgumentSchema[];
12	  example?: string;
13	  keywords?: string[];
14	}
15	
16	export class CommandTemplateManager {
17	  private templates = new Map<string, CommandTemplate>();
18	
19	  registerTemplate(template: CommandTemplate): void {
20	    this.templates.set(template.id, template);
21	  }
22	
23	  unregisterTemplate(templateId: string): void {
24	    this.templates.delete(templateId);
25	  }
26	
27	  getTemplate(templateId: string): CommandTemplate | undefined {
28	    return this.templates.get(templateId);
29	  }
30	
31	  getTemplates(): CommandTemplate[] {
32	    return Array.from(this.templates.values());
33	  }
34	
35	  getTemplatesByCategory(category: string): CommandTemplate[] {
36	    return Array.from(this.templates.values()).filter(t => t.category === category);
37	  }
38	
39	  renderTemplate(templateId: string, params: Record<string, string | number | boolean>): string {
40	    const template = this.templates.get(templateId);
41	    if (!template) {
42	      throw new Error(`Template ${templateId} not found`);
43	    }
44	
45	    let result = template.pattern;
46	    
47	    // Replace placeholders with actual values
48	    for (const [key, value] of Object.entries(params)) {
49	      const placeholder = `{{${key}}}`;
50	      result = result.replace(new RegExp(placeholder, 'g'), String(value));
51	    }
