154	// Macro templates - convert templates to macros
155	export const createMacroFromTemplate = (templateId: string, params: Record<string, string | number | boolean>): CommandMacro => {
156	  const template = templateManager.getTemplate(templateId);
157	  if (!template) {
158	    throw new Error(`Template ${templateId} not found`);
159	  }
160	
161	  const renderedPattern = templateManager.renderTemplate(templateId, params);
162	  const commands = renderedPattern.split(' && ').map(cmd => cmd.trim());
163	
164	  return createMacro({
165	    id: `template.${templateId}.${Date.now()}`,
166	    name: `${template.name}-${Object.values(params).join('-')}`,
167	    description: `Generated from template: ${template.description}`,
168	    category: template.category,
169	    keywords: template.keywords,
170	    steps: commands.map((command, index) => {
171	      const [commandName, ...args] = command.split(' ');
172	      return createMacroStep(
173	        commandName,
174	        args.length > 0 ? { args: args.join(' ') } : undefined,
175	        {
176	          condition: index === 0 ? 'always' : 'on-success',
177	          description: `Step ${index + 1}: ${command}`
178	        }
179	      );
180	    })
181	  });
182	};
