185	export const generateCommandFromTemplate = (template: CommandTemplate): Command => {
186	  return {
187	    id: `template.${template.id}`,
188	    name: template.name,
189	    description: `${template.description} (template)`,
190	    category: template.category,
191	    keywords: [...(template.keywords || []), 'template'],
192	    args: template.args,
193	    handler: async (args: Record<string, string | number | boolean>) => {
194	      try {
195	        const macro = createMacroFromTemplate(template.id, args);
196	        // This would execute the macro, but for now just return the pattern
197	        return `Template rendered: ${templateManager.renderTemplate(template.id, args)}`;
198	      } catch (error) {
199	        throw new Error(`Template execution failed: ${error instanceof Error ? error.message : String(error)}`);
200	      }
201	    }
202	  };
203	};

