10	// KV Store Tool - exposed via MCP with per-user namespacing
11	// This tool ONLY accesses the KV table, NOT the auth table
12	const KV_STORE_TOOL: Tool = {
13	  name: 'kvstore',
14	  description: 'Get or put an item in your personal key-value store. Keys are automatically namespaced per user.',
15	  inputSchema: {
16	    type: 'object',
17	    properties: {
18	      action: { type: 'string', enum: ['get', 'put'] },
19	      key: { type: 'string', description: 'Key for the item (will be automatically namespaced per user)' },
20	      value: { type: 'object', description: 'Value to store (for put action)' },
21	    },
22	    required: ['action', 'key'],
23	  },
24	  outputSchema: { type: 'object' },
25	  async call(args: { action: string; key?: string; value?: unknown }, username?: string) {
26	    if (!username) {
27	      return { content: [{ type: 'text', text: 'Unauthorized: No username provided' }], isError: true };
28	    }
29	
30	    if (!args.key) {
31	      return { content: [{ type: 'text', text: 'Missing key' }], isError: true };
32	    }
33	
34	    // Enforce per-user namespacing: prefix all keys with username
35	    const namespacedKey = `user:${username}:${args.key}`;
36	
37	    switch (args.action) {
38	      case 'get': {
39	        const data = await db.get({
40	          TableName: KV_TABLE_NAME,
41	          Key: { id: namespacedKey }
42	        }).promise();
43	        return {
44	          content: [{ type: 'text', text: JSON.stringify(data.Item?.value ?? null, null, 2) }],
45	          structuredContent: data.Item?.value ?? null,
46	        };
47	      }
48	      case 'put': {
49	        if (args.value === undefined) {
50	          return { content: [{ type: 'text', text: 'Missing value' }], isError: true };
51	        }
52	        await db.put({
53	          TableName: KV_TABLE_NAME,
54	          Item: {
55	            id: namespacedKey,
56	            username,
57	            key: args.key,
58	            value: args.value,
59	            updatedAt: Date.now()
60	          }
61	        }).promise();
62	        return { content: [{ type: 'text', text: 'OK' }], structuredContent: { ok: true } };
63	      }
64	      default:
65	        return { content: [{ type: 'text', text: 'Unknown action' }], isError: true };
66	    }
67	  },
68	};
