111	function toBase64Url(buf: Buffer) {
112	  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
113	}
114	
115	function fromBase64Url(str: string): ArrayBuffer {
116	  str = str.replace(/-/g, '+').replace(/_/g, '/');
117	  const pad = str.length % 4;
118	  if (pad) str += '='.repeat(4 - pad);
119	  const buffer = Buffer.from(str, 'base64');
120	  // CRITICAL FIX: buffer.buffer returns the ENTIRE pooled ArrayBuffer (8192 bytes),
121	  // but we only want the slice that contains our data. Without this, fido2-lib
122	  // receives incorrect data and fails with "id and credId were not the same".
123	  return buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength);
124	}
