126	async function getUser(username: string): Promise<UserRecord> {
127	  const id = `user#${username}`;
128	  const { Item } = await db.get({ TableName: TABLE_NAME, Key: { id } }).promise();
129	  if (Item) return Item as UserRecord;
130	  const user: UserRecord = {
131	    id,
132	    username,
133	    userId: toBase64Url(crypto.randomBytes(32)),
134	    credentials: [],
135	  };
136	  await db.put({ TableName: TABLE_NAME, Item: user }).promise();
137	  return user;
138	}
