144	// Token validation for protected endpoints
145	async function validateBearerToken(authHeader: string | undefined): Promise<string | null> {
146	  if (!authHeader?.startsWith('Bearer ')) return null;
147	
148	  const token = authHeader.substring(7);
149	
150	  try {
151	    const { Item } = await db.get({
152	      TableName: TABLE_NAME,
153	      Key: { id: `token#${token}` }
154	    }).promise();
155	
156	    if (!Item || Item.expiresAt < Date.now()) {
157	      return null;
158	    }
159	
160	    return Item.username;
161	  } catch (error) {
162	    console.error('Token validation error:', error);
163	    return null;
164	  }
165	}
