168	interface JsonRpcRequest {
169	  jsonrpc: string;
170	  id?: string | number | null;
171	  method: string;
172	  params?: unknown;
173	}
174	
175	interface JsonRpcResponse {
176	  jsonrpc: string;
177	  id: string | number | null;
178	  result?: unknown;
179	  error?: { code: number; message: string };
180	}
181	
182	function isObject(value: unknown): value is Record<string, unknown> {
183	  return typeof value === 'object' && value !== null;
184	}
185	
186	function validateRequest(value: unknown): value is JsonRpcRequest {
187	  return (
188	    isObject(value) &&
189	    value.jsonrpc === '2.0' &&
190	    typeof value.method === 'string'
191	  );
192	}
193	
194	async function handleMcpRequest(req: unknown, username?: string): Promise<JsonRpcResponse> {
195	  if (!validateRequest(req)) {
196	    return {
197	      jsonrpc: '2.0',
198	      id: null,
199	      error: { code: -32600, message: 'Invalid Request' },
200	    };
201	  }
202	  const validReq = req as JsonRpcRequest;
203	
204	  switch (validReq.method) {
205	    case 'capabilities':
206	      return {
207	        jsonrpc: '2.0',
208	        id: validReq.id ?? null,
209	        result: { resources: true, prompts: true, tools: true },
210	      };
211	    case 'echo':
212	      return {
213	        jsonrpc: '2.0',
214	        id: validReq.id ?? null,
215	        result: validReq.params ?? null,
216	      };
217	    case 'tools/list':
218	      return {
219	        jsonrpc: '2.0',
220	        id: validReq.id ?? null,
221	        result: {
222	          tools: Array.from(tools.values()).map(({ name, description, inputSchema, outputSchema }) => ({
223	            name,
224	            description,
225	            inputSchema,
226	            outputSchema,
227	          })),
228	        },
229	      };
230	    case 'tools/call':
231	      if (!isObject(validReq.params) || typeof validReq.params.name !== 'string') {
232	        return {
233	          jsonrpc: '2.0',
234	          id: validReq.id ?? null,
235	          error: { code: -32602, message: 'Invalid params' },
236	        };
237	      }
238	      const tool = tools.get(validReq.params.name);
239	      if (!tool) {
240	        return {
241	          jsonrpc: '2.0',
242	          id: validReq.id ?? null,
243	          error: { code: -32601, message: 'Tool not found' },
244	        };
245	      }
246	      const callArgs = isObject(validReq.params.arguments) ? validReq.params.arguments : {};
247	      // Pass username to tool for user namespacing
248	      const callResult = await tool.call(callArgs, username);
249	      return {
250	        jsonrpc: '2.0',
251	        id: validReq.id ?? null,
252	        result: callResult,
253	      };
254	    default:
255	      return {
256	        jsonrpc: '2.0',
257	        id: validReq.id ?? null,
258	        error: { code: -32601, message: 'Method not found' },
259	      };
260	  }
261	}
